def power(a, b, m):
    res = 1
    a = a % m
    while b > 0:
        if b % 2 == 1:
            res = (res * a) % m
        a = (a * a) % m
        b //= 2
    return res

m = 625
phi = 500
# Find the smallest divisor d of 500 such that 3^d = 1 mod 625
for d in range(1, phi + 1):
    if phi % d == 0:
        if power(3, d, m) == 1:
            print(f"Order k of 3 modulo 625 is: {d}")
            break
